const DATE_PATTERN = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysInMonth(year, month) {
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return MONTH_LENGTHS[month - 1];
}

function daysBeforeYear(year) {
  return (
    year * 365 +
    Math.floor((year + 3) / 4) -
    Math.floor((year + 99) / 100) +
    Math.floor((year + 399) / 400)
  );
}

const MIN_ORDINAL = 0;
const MAX_ORDINAL = daysBeforeYear(10000) - 1;
const EPOCH_ORDINAL = daysBeforeYear(1970);

function parseDate(value) {
  if (
    typeof value !== "string" ||
    value.length !== 10 ||
    !DATE_PATTERN.test(value)
  ) {
    throw new RangeError("Invalid calendar date");
  }

  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));

  if (
    month < 1 ||
    month > 12 ||
    day < 1 ||
    day > daysInMonth(year, month)
  ) {
    throw new RangeError("Invalid calendar date");
  }

  let ordinal = daysBeforeYear(year);

  for (let currentMonth = 1; currentMonth < month; currentMonth += 1) {
    ordinal += daysInMonth(year, currentMonth);
  }

  return ordinal + day - 1;
}

function formatOrdinal(ordinal) {
  if (ordinal < MIN_ORDINAL || ordinal > MAX_ORDINAL) {
    throw new RangeError("Result is outside the YYYY-MM-DD range");
  }

  let lowYear = 0;
  let highYear = 10000;

  while (lowYear + 1 < highYear) {
    const middleYear = Math.floor((lowYear + highYear) / 2);

    if (daysBeforeYear(middleYear) <= ordinal) {
      lowYear = middleYear;
    } else {
      highYear = middleYear;
    }
  }

  const year = lowYear;
  let dayOfYear = ordinal - daysBeforeYear(year);
  let month = 1;

  while (dayOfYear >= daysInMonth(year, month)) {
    dayOfYear -= daysInMonth(year, month);
    month += 1;
  }

  const day = dayOfYear + 1;

  return `${String(year).padStart(4, "0")}-${String(month).padStart(
    2,
    "0"
  )}-${String(day).padStart(2, "0")}`;
}

function dayOfWeek(ordinal) {
  const value = (ordinal - EPOCH_ORDINAL + 4) % 7;
  return value < 0 ? value + 7 : value;
}

function isWeekdayOrdinal(ordinal) {
  const weekday = dayOfWeek(ordinal);
  return weekday >= 1 && weekday <= 5;
}

function nextWeekdayAfter(ordinal) {
  let candidate = ordinal + 1;

  while (!isWeekdayOrdinal(candidate)) {
    candidate += 1;
  }

  return candidate;
}

function buildHolidayCalendar(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array");
  }

  const observed = new Set();
  const weekendHolidays = [];

  for (let index = 0; index < holidays.length; index += 1) {
    const ordinal = parseDate(holidays[index]);

    if (isWeekdayOrdinal(ordinal)) {
      observed.add(ordinal);
    } else {
      weekendHolidays.push(ordinal);
    }
  }

  const successors = new Map();

  function findFreeWeekday(ordinal) {
    let root = ordinal;

    while (successors.has(root)) {
      root = successors.get(root);
    }

    let current = ordinal;

    while (successors.has(current)) {
      const next = successors.get(current);
      successors.set(current, root);
      current = next;
    }

    return root;
  }

  function occupy(ordinal) {
    if (!successors.has(ordinal)) {
      successors.set(
        ordinal,
        findFreeWeekday(nextWeekdayAfter(ordinal))
      );
    }
  }

  for (const ordinal of observed) {
    occupy(ordinal);
  }

  weekendHolidays.sort((a, b) => a - b);

  for (const holiday of weekendHolidays) {
    const weekday = dayOfWeek(holiday);
    const nextMonday = holiday + (weekday === 6 ? 2 : 1);
    const observedDay = findFreeWeekday(nextMonday);

    observed.add(observedDay);
    occupy(observedDay);
  }

  return {
    observed,
    sortedObserved: Array.from(observed).sort((a, b) => a - b),
  };
}

function upperBound(values, target) {
  let low = 0;
  let high = values.length;

  while (low < high) {
    const middle = Math.floor((low + high) / 2);

    if (values[middle] <= target) {
      low = middle + 1;
    } else {
      high = middle;
    }
  }

  return low;
}

function countWeekdaysInclusive(first, last) {
  if (last < first) {
    return 0;
  }

  const length = last - first + 1;
  const fullWeeks = Math.floor(length / 7);
  const remainder = length % 7;
  const firstWeekday = dayOfWeek(first);
  let count = fullWeeks * 5;

  for (let offset = 0; offset < remainder; offset += 1) {
    const weekday = (firstWeekday + offset) % 7;

    if (weekday >= 1 && weekday <= 5) {
      count += 1;
    }
  }

  return count;
}

function businessDaysThrough(ordinal, calendar) {
  if (ordinal < MIN_ORDINAL) {
    return 0;
  }

  return (
    countWeekdaysInclusive(MIN_ORDINAL, ordinal) -
    upperBound(calendar.sortedObserved, ordinal)
  );
}

function countBusinessDaysOpenClosed(start, end, calendar) {
  if (end <= start) {
    return 0;
  }

  const weekdayCount = countWeekdaysInclusive(start + 1, end);
  const holidayCount =
    upperBound(calendar.sortedObserved, end) -
    upperBound(calendar.sortedObserved, start);

  return weekdayCount - holidayCount;
}

function isBusinessOrdinal(ordinal, calendar) {
  return (
    isWeekdayOrdinal(ordinal) && !calendar.observed.has(ordinal)
  );
}

function businessOrdinalByRank(rank, calendar) {
  const total = businessDaysThrough(MAX_ORDINAL, calendar);

  if (rank < 1 || rank > total) {
    throw new RangeError("Result is outside the YYYY-MM-DD range");
  }

  let low = MIN_ORDINAL;
  let high = MAX_ORDINAL;

  while (low < high) {
    const middle = Math.floor((low + high) / 2);

    if (businessDaysThrough(middle, calendar) >= rank) {
      high = middle;
    } else {
      low = middle + 1;
    }
  }

  return low;
}

export function isBusinessDay(date, holidays = []) {
  const ordinal = parseDate(date);
  const calendar = buildHolidayCalendar(holidays);

  return isBusinessOrdinal(ordinal, calendar);
}

export function addBusinessDays(date, n, holidays = []) {
  const ordinal = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer");
  }

  const calendar = buildHolidayCalendar(holidays);
  const totalBusinessDays = businessDaysThrough(MAX_ORDINAL, calendar);

  if (n === 0) {
    if (isBusinessOrdinal(ordinal, calendar)) {
      return formatOrdinal(ordinal);
    }

    const targetRank = businessDaysThrough(ordinal, calendar) + 1;

    if (targetRank > totalBusinessDays) {
      throw new RangeError("Result is outside the YYYY-MM-DD range");
    }

    return formatOrdinal(businessOrdinalByRank(targetRank, calendar));
  }

  if (n > 0) {
    const currentRank = businessDaysThrough(ordinal, calendar);
    const available = totalBusinessDays - currentRank;

    if (n > available) {
      throw new RangeError("Result is outside the YYYY-MM-DD range");
    }

    return formatOrdinal(
      businessOrdinalByRank(currentRank + n, calendar)
    );
  }

  const steps = -n;
  const precedingRank = businessDaysThrough(ordinal - 1, calendar);

  if (steps > precedingRank) {
    throw new RangeError("Result is outside the YYYY-MM-DD range");
  }

  return formatOrdinal(
    businessOrdinalByRank(precedingRank - steps + 1, calendar)
  );
}

export function businessDaysBetween(start, end, holidays = []) {
  const startOrdinal = parseDate(start);
  const endOrdinal = parseDate(end);
  const calendar = buildHolidayCalendar(holidays);

  if (startOrdinal === endOrdinal) {
    return 0;
  }

  if (startOrdinal < endOrdinal) {
    return countBusinessDaysOpenClosed(
      startOrdinal,
      endOrdinal,
      calendar
    );
  }

  const count = countBusinessDaysOpenClosed(
    endOrdinal,
    startOrdinal,
    calendar
  );

  return count === 0 ? 0 : -count;
}
